import { part as p, example, history, source, before, sample, s, op } from './authoring.mjs';
import { table, flow, challenge, q, tf } from './design-authoring.mjs';

const ref = (title, description, code, setup, interpretation, url) => ({ title, description: [description], code, language: 'python', setup, interpretation: [interpretation], source: source('Official API documentation', url), checkedOn: '2026-10-15' });
const withRef = (part, ...references) => ({ ...part, references });
function lesson(record) {
  const { checkpointAfter, checkpoint, ...rest } = record;
  const parts = record.parts.map((entry, i) => ({ ...entry, title: `${i + 1}. ${entry.title}` }));
  const technicalPart = { 'agent-pydantic-ai': 4, 'agent-langchain': 5, 'agent-langgraph': 3, 'agent-human-approval': 3, 'agent-mcp': 4 }[record.id];
  return { ...rest, section: 'Agents', parts, technicalStart: parts[technicalPart - 1].title, checkpoints: [{ after: parts[checkpointAfter - 1].title, title: `Questions on Parts 1 to ${checkpointAfter}`, questions: checkpoint }] };
}
const build = (title, problem, challenge, sources, cases, recipe, why, limitation, hints) => ({ title, problem, challenge, sources, cases, recipe, why, limitation, hints, extras: [], draftVersion: 1 });

const pydanticRecipe = `import os
from dataclasses import dataclass
from pydantic import BaseModel, ConfigDict, Field
from pydantic_ai import Agent, RunContext, ModelRetry

@dataclass
class Manuals:
    excerpts: dict[str, str]

class Answer(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    answer: str = Field(min_length=1)
    citations: list[str] = Field(min_length=1)

agent = Agent(
    os.environ["PERCEPTRON_LAB_AGENT_MODEL"],
    deps_type=Manuals,
    output_type=Answer,
    instructions="Read the supplied manual with read_manual. Cite its IDs. "
                 "Describe the manual; do not schedule work.",
)

@agent.tool
def read_manual(ctx: RunContext[Manuals]) -> dict[str, str]:
    """Read the manual excerpts available to this request."""
    return ctx.deps.excerpts

@agent.output_validator
def check_citations(ctx: RunContext[Manuals], answer: Answer) -> Answer:
    if not answer.answer.strip():
        raise ModelRetry("Answer text cannot be blank.")
    if any(key not in ctx.deps.excerpts for key in answer.citations):
        raise ModelRetry("Cite only IDs returned by read_manual.")
    return answer

result = agent.run_sync(
    "What should a technician check when pump P7 vibrates?",
    deps=Manuals({"manual-7": "Inspect the mounting and coupling."}),
)
print(result.output.model_dump())`;

const pydantic = lesson({
  id: 'agent-pydantic-ai', title: 'Give Botie a Typed Job with Pydantic AI', topic: 'Building with Agent Frameworks',
  appliedIn: [before('checking the meaning and destination of an answer', 'agent-output-guardrails')],
  blurb: 'Botie can read a manual, but the application still needs a usable answer and real citation IDs. Give the agent its dependencies and check what comes back.',
  openingTitle: 'The Answer Sounds Fine. Where Did That Citation Come From?',
  opening: ['A technician asks Botie what to inspect when a pump vibrates. The response includes a sensible sentence and a manual reference. Unfortunately, that reference was never in the material we gave him. How should the program notice before displaying it?', 'We have already built a tool loop and an output contract. Now we can give those responsibilities to a framework while keeping our own checks. Pydantic AI connects Python functions, typed results and the data belonging to a particular request.'],
  prerequisites: [before('Structured outputs', 'agent-structured-outputs'), before('Tool contracts', 'agent-tool-contracts'), before('Agent loops', 'agent-loops')],
  history: history('Making a Model Response Fit an Ordinary Python Application', [source('Pydantic AI v1 announcement', 'https://pydantic.dev/articles/pydantic-ai-v1'), source('Dependencies', 'https://ai.pydantic.dev/dependencies/'), source('Function tools', 'https://ai.pydantic.dev/tools/'), source('Output validation', 'https://ai.pydantic.dev/output/')], 'Application developers needed model responses that could be checked and passed to other code. The Pydantic team approached that problem through Python types, dependency injection and output validation. Its September 2025 v1 announcement describes those engineering concerns; the reference here uses the current documented interfaces.', 'The useful idea is familiar from the earlier lessons: make each boundary explicit. A request receives the manual data it may read, a tool exposes an operation, and the final answer must fit a declared structure. Our invented pump-manual example adds a citation check. It does not turn a well-formed sentence into a verified maintenance instruction.'),
  reading: { experimentTitle: 'Does this answer cite an available excerpt?', experimentIntro: 'Wire the field check before the citation check. Then change the proposed answer or the excerpts available to this run.', connectionTitle: 'Keep the answer contract beside the data it depends on', practiceTitle: 'Practice. Check Botie’s citation contract', outputLabel: 'Answer validation route', exampleNote: 'These are hand-authored candidate answers. No language model runs in the workshop.' },
  intuition: [table('The display needs fields it can read', 'An answer record carries text and a list of excerpt identifiers. The list is a collection of references, not a sentence that happens to contain commas.', ['Candidate', 'Answer field', 'Citations field'], [['Usable shape', 'Inspect the mounting.', '["manual-7"]'], ['Wrong shape', 'Inspect the mounting.', '"manual-7"']], 'A string and a list containing one string are different Python values.'), flow('Check the shape, then check the reference', 'A citation can be well formed and still refer to an absent excerpt.', [['Candidate answer', 'Text plus citation IDs'], ['Field check', 'Can the program read the declared structure?'], ['Evidence check', 'Does each ID exist in this run’s supplied excerpts?'], ['Content review', 'Do those excerpts actually support the answer?']], 'The workshop builds the first two checks. Content support needs its own evaluation.')],
  parts: [
    p('Give the program a result it can inspect', 'Suppose the interface has an answer panel and a source panel. An arbitrary paragraph forces the interface to guess where one ends and the other begins. A record with answer and citations fields gives each panel something named to read.\n\nWe use a Pydantic BaseModel to declare those fields. Constraints can require a nonempty list and reject unexpected keys. A declared type is a contract about representation. It does not establish that the answer is useful or true.', null, 'Keep the distinction visible when testing. A correctly shaped invented citation passes a type check and fails an evidence check.'),
    p('Pass the manual as a dependency', 'The excerpts belong to this request. Passing them into the run makes that relationship visible and lets a test substitute a small fixture. In Pydantic AI, deps_type describes the dependency type, while deps supplies the actual instance when the agent runs.\n\nRunContext gives a tool access to those application-provided dependencies. The model chooses tool arguments; it does not construct the authenticated user or database connection. A dependency might hold a scoped database client instead of our small dictionary. Enforce access inside that client or tool.', null, 'Do not paste a service credential into the prompt to make it available. Server code can use a credential without returning it as tool output.'),
    p('Expose a small read operation', 'The read_manual tool returns the excerpts allowed for the request. Its Python signature tells the framework what inputs exist, and its docstring describes the operation to the model. Our tool has no model-chosen arguments, which prevents the model from supplying another customer’s identity.\n\nThe returned dictionary still becomes information the model can use. If an excerpt contains text that tells Botie to ignore instructions, treat it as manual content. A tool result does not acquire authority over the application because it arrived through a Python function.', null, 'The tool’s job is reading evidence. Creating an inspection job will require a separate permission boundary later.'),
    withRef(p('Connect Agent, dependencies and output_type', 'Agent holds the model configuration and the permitted tool definitions. run_sync executes a run from an ordinary synchronous script; use await agent.run in an asynchronous server. The returned result has an output value matching the declared type when the run succeeds.\n\nThis recipe sends an invented excerpt to your chosen provider. Its output validator checks citation membership after the structural check. ModelRetry asks for a corrected response within the framework’s retry limits. Exhausted retries and provider failures still need an application error path.', null, 'Follow the names through the code: Manuals is request data, Answer is the result contract, and read_manual is an operation. They have different jobs.'), ref('A manual reader with a typed answer', 'This is a server-side reference recipe, separate from the offline Python challenge below.', pydanticRecipe, ['Create a Python environment and install pydantic-ai and pydantic. Resolve compatible versions, then record them in your project lockfile.', 'Set PERCEPTRON_LAB_AGENT_MODEL to a provider-qualified model available to you. Configure that provider’s credential in the server environment, for example OPENAI_API_KEY for an OpenAI-backed model. Never enter credentials into the browser worksheet.', 'Running this script makes a provider request and can incur charges. The generated wording varies; no output transcript is promised here.'], 'The program checks representation and citation membership. It deliberately does not execute maintenance work or claim that cited text entails the answer.', 'https://ai.pydantic.dev/output/')),
    p('A citation ID is only the start of evidence checking', 'An answer can cite manual-7 correctly while saying the opposite of its text. Membership asks whether we have that source. Entailment asks whether the source supports the claim. Those are different questions, so keep different tests for them.\n\nA useful fixture can contain two excerpts with different pump types. Then a response that cites the available but wrong pump manual should fail the task evaluation even though it passes our membership validator. Preserve the original excerpt and its version so a reviewer can understand the disagreement.', null, 'The workshop output says accept for content review. That wording names exactly what passed.'),
    p('Test the boundary before spending a model call', 'Start with deterministic unit tests of the tool and validators. Give the citation check an absent ID, an empty list, and an extra field. A live model is unnecessary for those cases.\n\nThen run provider-backed evaluation separately to investigate whether the model reads the right excerpt and handles missing evidence. Repeating those runs tells us something different from repeatedly checking a Python dictionary. Mocking the provider helps test control flow, but it cannot establish answer quality.', null, 'Our offline exercise implements the two boundary checks directly so you can see what the framework is organising.', [example('Test membership with a set', 'A set is useful when we only need to ask whether an identifier exists. The candidate list retains its original order.', 'available = {"manual-2", "manual-7"}\ncandidate_ids = ["manual-7", "manual-9"]\nmissing = [key for key in candidate_ids if key not in available]\nprint(missing)', "['manual-9']", 'The missing ID needs repair. The available ID still needs a content-support check.')]),
    p('Let a failed answer remain failed', 'If validation cannot produce a usable result, return a clear unsuccessful state to the application. Do not replace the answer with an empty success object, and do not keep retrying indefinitely. Record the failure category without logging credentials or unnecessary manual content.\n\nA technician can supply another excerpt or ask for review. That is a useful next step even when the agent has no supported answer. Later evaluation lessons will distinguish those justified refusals from failures to answer questions the manual could resolve.', null, 'A framework reduces repeated plumbing. The acceptance policy still belongs to the application.'),
  ], checkpointAfter: 4,
  checkpoint: [q('The result is {"answer":"Inspect the coupling.","citations":["manual-99"]}. Available excerpts are ["manual-7"].', 'Which check catches the shown problem?', ['Citation membership', 'Only checking that citations is a list', 'Changing the model temperature'], 0, 'The field has the expected list shape, but the referenced ID is absent.'), tf('A server passes a scoped database client through deps. The tool does not return its credentials.', 'The model needs the database password added to its prompt before the tool can use the client.', false, 'Python executes the tool with application dependencies. The model does not need the credential itself.')],
  quiz: [q('An answer cites manual-7, and manual-7 exists, but the answer contradicts its text.', 'What remains unverified?', ['Whether the source supports the claim', 'Whether the citation ID exists', 'Whether a string can be stored'], 0, 'Evidence membership cannot establish the meaning of the cited passage.'), tf('A unit test checks an offline validator with an invented absent citation.', 'This can test the validator without contacting a model provider.', true, 'The acceptance rule is deterministic Python code.')],
  practice: [challenge('Which candidate answers need repair?', ['Write answer_route(candidate, available). candidate is a dictionary whose only keys must be answer and citations. answer must be a nonblank string. citations must be a nonempty list of strings, all present in available, a list of strings. Return "accept for content review" or "repair answer". Malformed candidate values take the repair route; malformed available raises ValueError. Do not mutate the inputs.', 'Print the route for {"answer":"Inspect the coupling.","citations":["manual-2","manual-8"]} with available ["manual-2","manual-4"].'], 'def answer_route(candidate, available):\n    pass\n\nprint(answer_route({"answer":"Inspect the coupling.","citations":["manual-2","manual-8"]}, ["manual-2","manual-4"]))', 'def answer_route(candidate, available):\n    if not isinstance(available, list) or any(not isinstance(x, str) for x in available):\n        raise ValueError("Available IDs must be a list of strings")\n    if not isinstance(candidate, dict) or set(candidate) != {"answer", "citations"}:\n        return "repair answer"\n    text, ids = candidate["answer"], candidate["citations"]\n    valid = isinstance(text, str) and bool(text.strip())\n    valid = valid and isinstance(ids, list) and bool(ids)\n    valid = valid and all(isinstance(x, str) and x in available for x in ids)\n    return "accept for content review" if valid else "repair answer"\n\nprint(answer_route({"answer":"Inspect the coupling.","citations":["manual-2","manual-8"]}, ["manual-2","manual-4"]))', 'repair answer', ['Check the container and fields before reading them.', 'A string is iterable, so explicitly require citations to be a list before checking its members.'], [['Available evidence', 'assert answer_route({"answer":"Read the manual.","citations":["A"]}, ["A"]) == "accept for content review"'], ['Wrong container and blank answer', 'assert answer_route({"answer":" ","citations":["A"]}, ["A"]) == "repair answer"\nassert answer_route({"answer":"Read it.","citations":"A"}, ["A"]) == "repair answer"'], ['Extra fields and absent references', 'assert answer_route({"answer":"Check.","citations":["B"]}, ["A"]) == "repair answer"\nassert answer_route({"answer":"Check.","citations":["A"],"approved":True}, ["A"]) == "repair answer"'], ['Reject malformed available IDs', 'try:\n    answer_route({}, "A")\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("Expected ValueError")']])],
  build: build('Keep invented citations out of Botie’s answer', 'The maintenance interface needs a readable answer with references it can open.', 'Connect Check the answer fields to Check citation membership. Use the available excerpt IDs from this request. Return the resulting route.', { candidate: 'Candidate answer record', available: 'Excerpt IDs available to this run' }, [sample('A supported identifier', { candidate: { answer: 'Inspect the mounting.', citations: ['manual-7'] }, available: ['manual-7'] }, 'accept for content review'), sample('A citation to an absent manual', { candidate: { answer: 'Inspect the coupling.', citations: ['manual-99'] }, available: ['manual-7'] }, 'repair answer'), sample('A string where the list should be', { candidate: { answer: 'Inspect the mounting.', citations: 'manual-7' }, available: ['manual-7'] }, 'repair answer')], op('afEvidenceGate', op('afAnswerShape', s('candidate')), s('available')), 'The first check establishes the representation. The second compares identifiers with evidence supplied by the application.', 'This toy boundary does not judge whether the source entails the answer and does not run Pydantic AI or a language model.', ['Start with the record shape. A citation string is different from a list of citations.', 'The evidence check needs the field-check result on one input and the available IDs on the other.']),
});

const langchainRecipe = `import os
from langchain.agents import create_agent
from langchain.tools import tool
from langchain.agents.middleware import (
    ModelCallLimitMiddleware, ToolCallLimitMiddleware,
)

@tool
def read_manual(asset: str) -> dict:
    """Read the invented inspection excerpt for a pump asset."""
    manuals = {"P7": {"id": "manual-7", "text": "Inspect the mounting."}}
    return manuals.get(asset, {"error": "No excerpt for this asset"})

agent = create_agent(
    model=os.environ["PERCEPTRON_LAB_AGENT_MODEL"],
    tools=[read_manual],
    system_prompt="Answer from the manual and cite its ID. "
                  "If no excerpt exists, say so. Do not schedule work.",
    middleware=[
        ModelCallLimitMiddleware(run_limit=4, exit_behavior="error"),
        ToolCallLimitMiddleware(run_limit=2, exit_behavior="error"),
    ],
)
state = agent.invoke({"messages": [
    {"role": "user", "content": "What should I inspect on P7?"}
]})
print(state["messages"][-1].content)`;

const langchain = lesson({
  id: 'agent-langchain', title: 'Put Limits Around a LangChain Agent', topic: 'Building with Agent Frameworks',
  appliedIn: [before('reserving a shared run budget', 'agent-resource-budgets')],
  blurb: 'Botie keeps looking for a manual that does not exist. Use an agent runtime with explicit tool access and limits, then inspect the messages that explain its decisions.',
  openingTitle: 'How Many Times Should Botie Ask the Same Question?',
  opening: ['The manual reader works for pump P7. A technician then asks about P8, whose manual has not been uploaded. Botie tries another lookup, receives the same missing result, and tries again. The loop needs a stopping rule that does not depend on the model deciding it has done enough.', 'LangChain provides an agent runtime that coordinates messages and tools. We will keep the task small, give it a read-only tool, and put a call limit around execution. The workshop lets you build the permission and budget decision yourself.'],
  prerequisites: [before('Agent loops', 'agent-loops'), before('Pydantic AI', 'agent-pydantic-ai')],
  history: history('When Every Application Was Rebuilding the Same Loop', [source('LangChain and LangGraph v1', 'https://www.langchain.com/blog/langchain-langgraph-1dot0'), source('Agents', 'https://docs.langchain.com/oss/python/langchain/agents'), source('Tools', 'https://docs.langchain.com/oss/python/langchain/tools'), source('Middleware', 'https://docs.langchain.com/oss/python/langchain/middleware/overview'), source('Prebuilt middleware', 'https://docs.langchain.com/oss/python/langchain/middleware/built-in')], 'Agent applications repeatedly need to send messages, execute requested tools, and return the results to a model. LangChain’s v1 release organised a higher-level agent interface around create_agent, built on the LangGraph runtime. Middleware gives applications places to intervene in that repeated execution.', 'Our maintenance assistant makes the reason concrete. A missing manual should produce a bounded unsuccessful search. We will not infer a hard operational limit from a sentence asking the model to stop; we will enforce it in the program that executes calls.'),
  reading: { experimentTitle: 'May this requested lookup run?', experimentIntro: 'Combine the application’s permitted tool list with the remaining call budget. The output names the reason a request stops.', connectionTitle: 'A runtime needs checks at the execution boundary', practiceTitle: 'Practice. Enforce a tool-call policy', outputLabel: 'Tool execution route', exampleNote: 'This is a deterministic execution policy, not a simulation of a model deciding which tool to request.' },
  intuition: [table('Separate the request from permission to execute it', 'The model proposes read_manual. The server knows which tools are permitted and how many have executed.', ['Item', 'Supplied by', 'Purpose'], [['Tool name', 'Model proposal', 'Names the desired operation'], ['Allowed tools', 'Application', 'Restricts available authority'], ['Executed calls and limit', 'Runtime', 'Bounds additional work']], 'A model-proposed tool call does not grant itself permission.'), table('The same request can reach a different route', 'Assume read_manual is allowed and the execution limit is two calls.', ['Calls already executed', 'Requested tool', 'Route'], [['1', 'read_manual', 'Execute'], ['2', 'read_manual', 'Budget exhausted'], ['0', 'create_job', 'Denied']], 'This lesson checks permission before budget so a denied tool never becomes a permitted one.')],
  parts: [
    p('Know what create_agent is coordinating', 'A message describes what the technician asked. The model may return answer text or structured requests to call tools. The runtime executes permitted tools and adds their results to the conversation so the model can continue.\n\ncreate_agent constructs this repeated model-and-tool process. Its interface is useful when that loop fits the task. If every step is predetermined, a small ordinary function may be clearer. Reaching for an agent is a design choice, not a requirement for using a language model.', null, 'We are using the same maintenance question as before so the runtime change does not hide a change in the task.'),
    p('Keep messages paired with their tool results', 'A model response can contain a tool-call ID as well as a tool name and arguments. The result must refer to the matching call. That pairing lets the next model request distinguish one lookup from another, including when several tools were requested together.\n\nDo not reduce the whole conversation to the last sentence while debugging. Inspect which arguments were requested and which result came back. An empty lookup and a network failure need different handling even if both prevented a useful answer.', null, 'LangChain returns agent state containing messages. The final message alone can hide the reason a run became expensive.', [example('Find the result belonging to a lookup', 'These ordinary Python dictionaries represent an invented trace, not LangChain message objects. The list retains arrival order; the call ID establishes which request a result belongs to.', 'requested = {"id": "call-7", "name": "read_manual", "args": {"asset": "P7"}}\nresults = [\n    {"call_id": "call-8", "found": False},\n    {"call_id": "call-7", "found": True},\n]\nmatched = next(item for item in results if item["call_id"] == requested["id"])\nprint(requested["args"]["asset"])\nprint(matched["found"])', 'P7\nTrue', 'Nested dictionary access reads the requested asset. The matching result can appear later in the list, so using the first result would attach the wrong outcome to this lookup.')]),
    p('Make the tool small enough to describe precisely', 'The @tool decorator uses a Python function as a tool definition. Type annotations describe the arguments, while the docstring tells the model what the operation does. Our example accepts an asset ID and returns either an excerpt or an explicit missing result.\n\nFor a real service, scope the lookup to the authenticated technician’s permitted equipment before reading data. The model-supplied asset string is a request, not evidence that the user owns that asset. A service layer can enforce that check regardless of which framework invokes it.', null, 'The example’s one-entry dictionary is deliberately invented. It demonstrates lookup semantics without giving the agent access to real maintenance records.'),
    p('Use middleware where the operation happens', 'Middleware is code that runs at defined points around the agent loop. Hooks can inspect model requests or wrap tool execution. This gives the application a place to enforce limits and record what happened without burying every check in prompt text.\n\nA limit on model calls and a limit on tool calls measure different things. One model response may request several tools. Choose the quantity that bounds the work you care about, and make the stopping behaviour visible to the caller.', null, 'The workshop checks an individual tool request against a count of executed calls. It is a small policy exercise, not a reproduction of every framework middleware counter.'),
    withRef(p('Build the bounded reader', 'This server recipe uses create_agent with the read_manual tool and separate model and tool limits. The selected error behaviour raises when a limit is exceeded. In a web service, catch that failure at the application boundary and return an unsuccessful result the interface can explain.\n\nThe tool only reads from a fixture. There is no create_job tool to call. Keep that narrow surface while learning how the messages and limits behave, then add capabilities with their own tests.', null, 'Provider responses vary. Compare the actual call sequence and final evidence with the task requirements instead of copying a displayed answer.'), ref('A reader with separate model and tool limits', 'This reference is for your own Python service environment. The browser exercise uses no external provider.', langchainRecipe, ['Install a compatible LangChain 1.x release and your model integration, such as langchain-openai for an OpenAI-backed model. Record resolved versions in a lockfile.', 'Set PERCEPTRON_LAB_AGENT_MODEL to a provider-qualified identifier your integration accepts, and configure its credential on the server. Provider requests may incur charges.', 'Run the script as a local Python program with invented data. Add application exception handling before exposing it as a service.'], 'The two middleware limits bound different operations. This example uses per-run limits; a limit across a thread additionally needs persistent thread state.', 'https://docs.langchain.com/oss/python/langchain/middleware/built-in')),
    p('A retry needs a reason and a budget', 'A temporary connection failure may justify another attempt. An asset absent from the catalogue generally needs different evidence, not immediate repetition of the same lookup. Classify these outcomes before choosing retries.\n\nWhen an operation changes external state, a timeout can mean the effect happened but the reply was lost. Retrying create_job blindly can create a duplicate. Keep write operations separate from our read example and give them an idempotency key that the receiving service enforces.', null, 'A bounded retry can still repeat a mistake. Investigate whether another attempt can supply information the previous attempt lacked.'),
    p('Keep policy checks outside model-written arguments', 'Our offline gate receives the allowed tool names and used-call count from trusted application state. It checks permission first, then whether another execution fits. These inputs must not come from the model’s claim that it has permission or from its own reported count.\n\nFor concurrent requests, reserving budget needs an atomic operation in shared state. A pair of workers can both read one remaining slot unless the runtime coordinates them. The worksheet is sequential so that you can inspect the underlying comparison before adding concurrency.', 'Allowed = ["read_manual"]\nUsed calls = 2\nLimit = 2\nRequested = "read_manual"\nNext route = "budget exhausted"', 'The limit is reached when used calls equals the limit. There is no spare call at equality.'),
    p('Decide whether a framework is helping this particular job', 'Keep a small set of maintenance fixtures while trying implementations. Does each version preserve citation IDs, reject disallowed operations and stop when evidence is missing? Can you inspect a failure without reading framework internals?\n\nPydantic AI and LangChain both support more than the features introduced here. Compare the behaviour your service needs and the code your team can maintain. Moving to a larger abstraction does not remove the need for the contracts we have already built.', null, 'The next lesson takes explicit control of state transitions when a single model-tool loop no longer describes the work clearly.'),
  ], checkpointAfter: 4,
  checkpoint: [q('A model response requests three tools. Only one model request produced that response.', 'Why might a model-call limit be insufficient to bound tool work?', ['A single model call can request several tools', 'Every tool is free', 'Tool execution never repeats'], 0, 'Model calls and tool calls count different operations.'), tf('Only read_manual is in the tool allowlist. The model asks for create_job and two calls remain.', 'Remaining budget grants permission to create the job.', false, 'The tool is still disallowed. Permission and budget are separate checks.')],
  quiz: [q('A create_job request times out. The server might already have created the job.', 'What should a retry design address?', ['Duplicate effects using an enforced idempotency key', 'Only increasing the model temperature', 'Removing the execution log'], 0, 'A lost response does not prove that the action failed.'), tf('A fixture deliberately contains no P8 manual, and the agent reaches its call limit.', 'The application should report that it did not obtain a supported answer.', true, 'A stopped search is not a successful answer.')],
  practice: [challenge('Should the next tool call execute?', ['Write tool_route(name, allowed, used, limit). name is a string, allowed is a list of strings, and used and limit are nonnegative Python integers excluding booleans. Invalid input raises ValueError. Return "denied" for a name outside allowed, "budget exhausted" when used >= limit, or "execute " followed by the name. Check permission before budget.', 'Print the route for read_manual, allowed [read_manual], used 3 and limit 3.'], 'def tool_route(name, allowed, used, limit):\n    pass\n\nprint(tool_route("read_manual", ["read_manual"], 3, 3))', 'def tool_route(name, allowed, used, limit):\n    if not isinstance(name, str) or not isinstance(allowed, list) or any(not isinstance(x, str) for x in allowed):\n        raise ValueError("Use a tool name and list of allowed names")\n    if any(type(x) is not int or x < 0 for x in (used, limit)):\n        raise ValueError("Counts must be nonnegative integers")\n    if name not in allowed:\n        return "denied"\n    if used >= limit:\n        return "budget exhausted"\n    return "execute " + name\n\nprint(tool_route("read_manual", ["read_manual"], 3, 3))', 'budget exhausted', ['Permission is independent of budget.', 'Equality with the limit means there is no remaining execution slot.'], [['A remaining slot', 'assert tool_route("read_manual", ["read_manual"], 1, 2) == "execute read_manual"'], ['Denied even with exhausted budget', 'assert tool_route("create_job", ["read_manual"], 2, 2) == "denied"'], ['Zero budget', 'assert tool_route("read_manual", ["read_manual"], 0, 0) == "budget exhausted"'], ['Reject boolean counts', 'try:\n    tool_route("read_manual", [], True, 2)\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("Expected ValueError")']])],
  build: build('Stop Botie’s repeated manual lookup', 'The model asks for another tool call. The runtime must check its authority and remaining execution budget.', 'Connect the requested name and allowlist to Check the tool permission. Pass that result, used calls and maximum calls to Apply the call budget. Return the route.', { name: 'Requested tool name', allowed: 'Application tool allowlist', used: 'Calls already executed', limit: 'Maximum executed calls' }, [sample('One lookup slot remains', { name: 'read_manual', allowed: ['read_manual'], used: 1, limit: 2 }, 'execute read_manual'), sample('The missing manual exhausted the budget', { name: 'read_manual', allowed: ['read_manual'], used: 2, limit: 2 }, 'budget exhausted'), sample('A write tool was never allowed', { name: 'create_job', allowed: ['read_manual'], used: 0, limit: 2 }, 'denied')], op('afBudgetRoute', op('afToolPolicy', s('name'), s('allowed')), s('used'), s('limit')), 'The execution boundary checks permission and a runtime count, regardless of what the model claims in its request.', 'This is a sequential policy gate. A production runtime must enforce counters atomically and handle provider errors, cancellation and side effects.', ['The permission check takes the name and the allowed list.', 'Apply the call budget consumes the permission result, not the raw tool name.']),
});

const graphRecipe = `from typing import Annotated, TypedDict
from langgraph.graph import StateGraph, START, END
from langgraph.checkpoint.memory import InMemorySaver
from langgraph.types import interrupt, Command

def merge_evidence(old: list[dict], incoming: list[dict]) -> list[dict]:
    by_id = {item["id"]: dict(item) for item in old}
    for item in incoming:
        by_id[item["id"]] = dict(item)
    return list(by_id.values())

class State(TypedDict):
    evidence: Annotated[list[dict], merge_evidence]
    approved: bool

def collect(state: State):
    return {"evidence": [
        {"id": "manual-7", "text": "Inspect the mounting."}
    ]}

def review(state: State):
    decision = interrupt({"evidence": state["evidence"]})
    return {"approved": decision is True}

builder = StateGraph(State)
builder.add_node("collect", collect)
builder.add_node("review", review)
builder.add_edge(START, "collect")
builder.add_edge("collect", "review")
builder.add_edge("review", END)
graph = builder.compile(checkpointer=InMemorySaver())

config = {"configurable": {"thread_id": "maintenance-request-17"}}
paused = graph.invoke({"evidence": [], "approved": False}, config)
print(paused["__interrupt__"])
# In a service, obtain this decision from an authenticated reviewer.
resumed = graph.invoke(Command(resume=True), config)
print(resumed["approved"])`;

const langgraph = lesson({
  id: 'agent-langgraph', title: 'Resume Botie’s Work with LangGraph', topic: 'Building with Agent Frameworks',
  appliedIn: [before('recovering from a reply that never arrived', 'agent-retries-and-effects')],
  blurb: 'The technician returns after a pause. Preserve the right request’s evidence, merge updates deliberately, and resume a review without repeating an external action.',
  openingTitle: 'The Technician Comes Back. Does Botie Remember the Right Job?',
  opening: ['Botie has found a manual excerpt and prepared a proposed inspection. The technician needs to ask a colleague before continuing. Closing the page should not turn that request into an unrelated conversation or repeat work that already happened.', 'We need an explicit record of where the request stopped and what information it had. LangGraph represents work as nodes connected by routes, with state passed between them. We will start by deciding what to preserve before adding pause and resume.'],
  prerequisites: [before('LangChain agents', 'agent-langchain'), before('Context', 'agent-context')],
  history: history('A Useful Workflow Sometimes Needs to Go Around Again', [source('LangGraph announcement, January 2024', 'https://www.langchain.com/blog/langgraph'), source('Graph API', 'https://docs.langchain.com/oss/python/langgraph/graph-api'), source('Persistence', 'https://docs.langchain.com/oss/python/langgraph/persistence'), source('Interrupts', 'https://docs.langchain.com/oss/python/langgraph/interrupts')], 'A fixed sequence of language-model calls can work until an early step returns insufficient evidence. The application then needs a route back to retrieval, or a pause for a person. LangGraph’s January 2024 introduction described cycles and explicit state machines as a way to control those paths.', 'For Botie, the state contains the evidence gathered for one maintenance request. A node returns an update, and the application decides how that update changes what was already stored. The workshop builds that merge operation on small invented records before the reference code introduces a paused graph.'),
  reading: { experimentTitle: 'What evidence should survive this update?', experimentIntro: 'Choose the request checkpoint, then merge incoming excerpts by ID. Observe what happens when a lookup returns an excerpt already seen.', connectionTitle: 'A saved request needs explicit update rules', practiceTitle: 'Practice. Merge evidence without duplicating a replay', outputLabel: 'Updated evidence records', exampleNote: 'The workshop demonstrates a reducer on checkpoint fixtures. It does not run the LangGraph scheduler.' },
  intuition: [table('A checkpoint belongs to one request', 'Two technicians can discuss the same pump without sharing the same unfinished task.', ['Thread', 'Saved evidence', 'Incoming update'], [['request-17', 'manual-7: old text', 'manual-7: revised text'], ['request-28', 'manual-2: other pump', 'No update']], 'Only the selected request should change.'), table('Choose a merge rule instead of hoping a list does the right thing', 'Our policy keeps the position of an existing ID and replaces its text. New IDs go at the end.', ['Before', 'Update', 'After'], [['manual-7: old', 'manual-7: revised', 'manual-7: revised'], ['manual-7: revised', 'manual-8: appendix', 'manual-7: revised; manual-8: appendix']], 'Blind concatenation would keep duplicate IDs and conflicting versions.')],
  parts: [
    p('Give the unfinished request a state', 'State is the data the workflow needs as it moves between operations. For our request, it includes collected evidence and whether review has happened. A thread ID identifies the request whose saved state we want to continue.\n\nKeep this ID separate from the asset ID. A pump can have several maintenance requests. Also keep it separate from user identity: the application must check that the signed-in user may access the selected thread. Knowing or guessing an ID does not grant access.', null, 'Write down which fields belong to the request before choosing how to save them. Otherwise unrelated concerns accumulate in one unstructured transcript.'),
    p('Make nodes return updates', 'A node is a function that performs one step and returns changes to state. A retrieval node can return new evidence. A review node can return a decision. Edges describe which node runs next; a conditional edge chooses a route from the current result.\n\nThis can describe deterministic work as well as model calls. Our reference uses an invented manual lookup so that the behaviour of the graph is easier to isolate. Adding a model inside a node does not change the need to define that node’s inputs and outputs.', null, 'Use a fixed route when the sequence is known. Add a conditional route or cycle only when the task actually needs one.'),
    p('Decide what an update means for each field', 'If a node returns a new approved value, replacing the previous boolean is sensible. Evidence is different: replacing the whole list may lose earlier excerpts, while appending everything may duplicate a repeated lookup.\n\nA reducer is the function that combines a previous field value with an incoming update. Our evidence reducer uses each excerpt’s ID. New IDs are appended, and existing IDs receive their updated text in place. This is an application policy, not LangGraph’s automatic rule for every list.', 'Before = [{"id":"manual-7","text":"old wording"}]\nUpdate = [{"id":"manual-7","text":"revised wording"}]\nAfter = [{"id":"manual-7","text":"revised wording"}]', 'The same update applied twice leaves one excerpt. That makes this particular merge idempotent: repeating it has the same result as applying it once.', [example('Replace one identified excerpt', 'A dictionary uses the excerpt ID as its key. Assigning that existing key replaces its value without adding another entry. dict creates a new outer dictionary for this small mapping of strings.', 'saved = {"M2": "Old coupling wording.", "M5": "Inspect the filter."}\nupdated = dict(saved)\nupdated["M2"] = "Revised coupling wording."\nprint(list(updated))\nprint(updated["M2"])\nprint(saved["M2"])', "['M2', 'M5']\nRevised coupling wording.\nOld coupling wording.", 'The ID stays in its original position and the saved mapping stays unchanged. The later challenge generalises this operation to lists of evidence records.')]),
    p('Messages and evidence need different reducers', 'LangGraph has an add_messages reducer for message histories. It can append messages and handle updates using message IDs. Our evidence records are ordinary dictionaries, so the example supplies a different reducer for them.\n\nDo not reuse the word id without deciding what it identifies. A tool-call ID, message ID and document ID name different objects. If two document revisions need to remain separately citable, use versioned document identifiers instead of overwriting one ID’s text.', null, 'The workshop’s replace-by-ID policy is chosen for this fixture. An audit trail should retain the prior version somewhere separate when the application needs it.'),
    p('Save a checkpoint that can actually survive the pause', 'A checkpointer stores graph state for a thread so a later invocation can continue it. InMemorySaver is convenient for learning, but its contents disappear when that Python process ends. A production service needs an appropriate persistent backend and an access policy for the saved data.\n\nA store is a different persistence mechanism for application data shared across threads. Keep a technician’s preference separate from the unfinished state of a particular inspection request. Retention and deletion rules apply to both.', null, 'An in-memory demonstration of resume is not a demonstration of crash recovery across process restarts.'),
    withRef(p('Pause at review and resume the same thread', 'interrupt exposes a value to the caller and pauses execution. When the application later invokes the same graph and thread with Command(resume=...), that value becomes the result of the interrupt call. The code in the interrupted node begins again on resume.\n\nThe reference pauses after collecting an invented excerpt. The automatic True near the end stands in for the service’s authenticated review handler. It is useful for observing control flow, but it is not an approval system.', null, 'Use the same thread configuration for resume. Creating a new thread would describe a new request rather than continuing the paused one.'), ref('A small graph that pauses with its evidence', 'This local reference uses no language model and requires no provider key. It demonstrates graph APIs outside the browser worksheet.', graphRecipe, ['Create a Python environment and install a compatible LangGraph 1.x release. Record resolved versions in a lockfile.', 'Run as a local script. InMemorySaver persists only while this process remains alive.', 'The sample uses a fixed review value to demonstrate resume. A deployed handler must authenticate the reviewer and bind the decision to the exact proposed action.'], 'The reducer controls evidence updates. The checkpointer controls saved thread state. Neither gives permission to execute an external action.', 'https://docs.langchain.com/oss/python/langgraph/interrupts')),
    p('Keep replay away from unprotected side effects', 'Imagine creating a work order before the review node pauses. Resuming the node could run that statement again. Now the technician has two orders even though there was one request. Place the effect after the decision, and still design the operation to tolerate retries and process failures.\n\nAn idempotency key lets the work-order service recognise the same intended action. The receiving service must store and enforce that key, ideally atomically with creation. A local set of completed IDs does not protect against a crash between creating the order and recording its ID.', null, 'Checkpointing the graph and making external effects idempotent solve related but different problems. Neither creates a universal exactly-once guarantee.'),
    p('Concurrent updates need a deliberate conflict policy', 'Two retrieval branches may find different text under the same document ID. Our simple last-update-wins reducer assumes an ordered update stream. If the order is not meaningful, the answer can depend on which result reaches it last.\n\nUse immutable versioned IDs, reject conflicting updates, or define an ordering from trusted revision information. Choose a rule that matches the source system. Adding a reducer removes an implementation ambiguity only when its policy is appropriate for the data.', null, 'The workshop is sequential. Its fixtures make the update order explicit rather than claiming to settle concurrent document conflicts.'),
    p('Follow the saved evidence through a changed request', 'Select another thread in the workshop and run the same construction. It should load that thread’s excerpts before applying its update. Then replay an existing excerpt and check that one ID remains.\n\nIf the old machine simply concatenated lists, the repeated-lookup fixture exposes the mistake. If it hard-coded one thread’s evidence, the other-request fixture exposes that instead. These are different failure modes, so keep both checks after making a repair.', null, 'The Python challenge asks you to write the merge operation without mutating either input. Saved state is easier to reason about when an update does not quietly rewrite the fixture used by another test.'),
  ], checkpointAfter: 4,
  checkpoint: [q('Saved evidence is [{"id":"M7","text":"old"}]. Incoming evidence is [{"id":"M7","text":"new"}]. This lesson replaces text for an existing ID.', 'What should remain after the merge?', ['One M7 record with text new', 'Two M7 records with conflicting text', 'An empty list'], 0, 'The update replaces the existing record in its original position.'), tf('A graph uses InMemorySaver and its Python process exits.', 'That memory checkpointer alone preserves the thread across the restart.', false, 'The data was in process memory. A persistent backend is needed across restarts.')],
  quiz: [q('A node writes a work order before calling interrupt. The reviewer later resumes it.', 'Which behaviour must the application account for?', ['Code before the interrupt runs again when the node resumes', 'The Python instruction pointer is restored without rerunning code', 'Every external write is automatically deduplicated'], 0, 'Keep effects carefully placed and make the external operation retry-safe.'), tf('An application checks access to a saved thread before loading it.', 'This is still necessary even when thread IDs are difficult to guess.', true, 'An identifier selects state; it does not establish authority to read it.')],
  practice: [challenge('Can a repeated lookup update evidence without duplicating it?', ['Write merge_evidence(old, incoming). Both inputs must be lists of dictionaries with a nonempty string id and a string text. Ignore extra record fields. Invalid inputs raise ValueError. Return new dictionaries in a new list. Keep the position where each ID first appeared, replace its text with the last value seen, and never mutate either input.', 'Print the merge of [{"id":"M2","text":"initial"}] and [{"id":"M2","text":"revised"},{"id":"M5","text":"appendix"}].'], 'def merge_evidence(old, incoming):\n    pass\n\nprint(merge_evidence([{"id":"M2","text":"initial"}], [{"id":"M2","text":"revised"},{"id":"M5","text":"appendix"}]))', 'def merge_evidence(old, incoming):\n    if not isinstance(old, list) or not isinstance(incoming, list):\n        raise ValueError("Evidence must be lists")\n    by_id = {}\n    for item in old + incoming:\n        if not isinstance(item, dict) or not isinstance(item.get("id"), str) or not item["id"] or not isinstance(item.get("text"), str):\n            raise ValueError("Each excerpt needs an id and text")\n        by_id[item["id"]] = {"id":item["id"], "text":item["text"]}\n    return list(by_id.values())\n\nprint(merge_evidence([{"id":"M2","text":"initial"}], [{"id":"M2","text":"revised"},{"id":"M5","text":"appendix"}]))', "[{'id': 'M2', 'text': 'revised'}, {'id': 'M5', 'text': 'appendix'}]", ['Python dictionaries preserve insertion order. Replacing a value does not move its key.', 'Copy each retained record so changing a result cannot rewrite an input.'], [['Replaying an update is idempotent', 'update = [{"id":"X","text":"a"}]\nonce = merge_evidence([], update)\nassert merge_evidence(once, update) == once'], ['Existing position and last value', 'assert merge_evidence([{"id":"A","text":"a"},{"id":"B","text":"b"}], [{"id":"A","text":"new"}]) == [{"id":"A","text":"new"},{"id":"B","text":"b"}]'], ['No shared mutable record', 'old = [{"id":"A","text":"original"}]\nresult = merge_evidence(old, [])\nresult[0]["text"] = "changed"\nassert old[0]["text"] == "original"'], ['Reject missing identity', 'try:\n    merge_evidence([], [{"text":"unlabelled"}])\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("Expected ValueError")']])],
  build: build('Restore the request before merging the manual update', 'A technician resumes a maintenance request while a revised excerpt arrives. Keep that request’s evidence coherent.', 'Load the selected thread’s evidence from the checkpoint records. Merge incoming records by ID, keeping first-seen positions and the last text for each ID. Return the updated evidence list.', { checkpoints: 'Evidence lists saved by thread ID', thread: 'Thread to resume', incoming: 'New or revised excerpt records' }, [sample('Append another manual excerpt', { checkpoints: { 'request-17': [{ id: 'M7', text: 'Inspect mounting.' }] }, thread: 'request-17', incoming: [{ id: 'M8', text: 'Check alignment.' }] }, [{ id: 'M7', text: 'Inspect mounting.' }, { id: 'M8', text: 'Check alignment.' }]), sample('The lookup returns a revised excerpt', { checkpoints: { 'request-17': [{ id: 'M7', text: 'Old wording.' }] }, thread: 'request-17', incoming: [{ id: 'M7', text: 'Revised mounting check.' }] }, [{ id: 'M7', text: 'Revised mounting check.' }]), sample('Another technician’s request', { checkpoints: { 'request-17': [{ id: 'M7', text: 'Mounting.' }], 'request-28': [{ id: 'M2', text: 'Filter.' }] }, thread: 'request-28', incoming: [{ id: 'M3', text: 'Intake.' }] }, [{ id: 'M2', text: 'Filter.' }, { id: 'M3', text: 'Intake.' }])], op('afMergeEvidence', op('afLoadThread', s('checkpoints'), s('thread')), s('incoming')), 'Thread selection preserves request identity. The reducer preserves evidence identity within that request.', 'This is a sequential reducer demonstration. It does not persist real data, resolve concurrent conflicting versions, or execute an external job.', ['Load the checkpoint belonging to the supplied thread before merging.', 'Merge evidence by ID replaces an existing record’s text and appends new IDs.']),
});

const approval = lesson({
  id: 'agent-human-approval', title: 'Ask Before Botie Creates the Inspection Job', topic: 'State and Permissions',
  appliedIn: [before('enforcing the caller’s current scope', 'agent-authorization')],
  blurb: 'A technician approves one inspection, then the proposal changes. Bind the decision to what was reviewed and check it again where the job is created.',
  openingTitle: 'The Technician Said Yes. Yes to Which Job?',
  opening: ['Botie proposes inspecting pump P7. The technician approves, then a follow-up message changes the asset to P9. If the program remembers only approved = True, it may apply the old decision to a job nobody reviewed.', 'We need a record of the particular proposal the person saw. Then the execution service can compare that record with what it is about to do. A pause in the interface is useful only if the permission survives that comparison.'],
  prerequisites: [before('Resuming a graph', 'agent-langgraph'), before('Tool contracts', 'agent-tool-contracts')],
  history: history('Permission Has to Belong to an Operation', [source('Saltzer and Schroeder: The Protection of Information in Computer Systems', 'https://web.mit.edu/Saltzer/www/publications/protection/'), source('LangGraph interrupts', 'https://docs.langchain.com/oss/python/langgraph/interrupts')], 'Long before language-model agents, shared computer systems needed to control who could read or change an object. Saltzer and Schroeder’s 1975 account describes protection mechanisms and distinguishes authentication from authorisation. Their discussion also includes requirements for human judgement before granting access.', 'An inspection assistant adds generated proposals to that old problem. It still needs a trusted component that grants access to a particular operation. Our approval record is a teaching design for binding a decision to a proposal. It is not a claim that a language model, a checkbox or a checkpoint supplies that authority automatically.'),
  reading: { experimentTitle: 'Does this approval still cover the proposed job?', experimentIntro: 'Compare the action fields, check the expiry and require the reviewer’s current permission. Change one field to see which check stops execution.', connectionTitle: 'Carry a decision with the action it actually approved', practiceTitle: 'Practice. Check an action-bound approval', outputLabel: 'Inspection authorisation route', exampleNote: 'All records are invented trusted fixtures. The workshop does not authenticate a reviewer or create an inspection job.' },
  intuition: [table('A yes needs something specific to refer to', 'The proposal identifies the maintenance request as well as the asset and operation. Its revision changes when the reviewed details change.', ['Field', 'Approved snapshot', 'Current proposal'], [['requestId', 'R17', 'R17'], ['asset', 'P7', 'P9'], ['operation', 'inspect', 'inspect'], ['revision', '1', '2']], 'The old approval cannot authorise the changed proposal.'), flow('Keep the decision at the execution boundary', 'The backend retrieves the authoritative review record and evaluates it against the action it will submit.', [['Compare', 'Same request, asset, operation and revision'], ['Check time', 'Current time is before expiry'], ['Check reviewer', 'Reviewer still has the required permission'], ['Execute or review', 'All checks pass, or request a new decision']], 'A model-provided statement that a person approved is not the authoritative record.')],
  parts: [
    p('Separate preparing a job from submitting it', 'Reading a manual and drafting a proposed inspection can happen before anyone grants permission to create a work order. Keep the proposal as data that a technician can inspect. The final write should be a distinct operation with a clear permission check.\n\nOur proposal names requestId, asset, operation and revision. A real proposal would also include every consequential argument, such as timing, assignee and affected site. If a field can change what the action does, it belongs in the reviewed snapshot.', null, 'A description such as perform maintenance is too vague to bind to a later write. Show the concrete action the receiving system will get.'),
    p('Record what the person actually reviewed', 'The approval record includes the proposal’s identity and revision, the decision, and an expiry. The service also records the authenticated reviewer and evaluates their authority. These records come from the review service, not from text generated by Botie.\n\nIf the reviewer edits a proposal, the application needs a new approved snapshot for those edited values. Do not approve the old object and quietly mutate it afterwards. Store immutable versions or compare a canonical digest of the complete approved payload.', null, 'A digest can identify a payload, but it is not a signature and it does not authenticate who approved it. The trusted server record is still required.', [example('Show the reviewer which fields changed', 'The tuple names the fields in a fixed display order. Both dictionaries supply every named field. The list comprehension retains the names whose values differ.', 'reviewed = {"asset": "P7", "operation": "inspect", "revision": "1"}\ncurrent = {"asset": "P9", "operation": "inspect", "revision": "2"}\nfields = ("asset", "operation", "revision")\nchanged = [key for key in fields if current[key] != reviewed[key]]\nprint(changed)', "['asset', 'revision']", 'The operation label stayed inspect, but its target and revision changed. This diagnostic helps explain why the complete approval gate must request another review.')]),
    p('Recheck the decision immediately before the effect', 'Our toy gate requires matching action fields, an unexpired approval and a reviewer who is currently permitted. It treats a missing or mismatched condition as a request for review. The current time comes from the server; the model cannot extend expiry by supplying its own clock.\n\nA production write should bind this check to the exact action being committed. Otherwise another request could change the proposal between checking it and creating the job. Use an immutable action version and a transaction or equivalent concurrency control in the service that owns the effect.', 'Approved asset = P7\nCurrent asset = P9\nAction match = false\nUnexpired = true\nReviewer permitted = true\nRoute = request review', 'Remaining time and an authorised reviewer do not repair a mismatch in the action itself.'),
    p('Make expiry and revocation visible', 'An approval can become inappropriate while a workflow waits. The pump may have been serviced already, the reviewer’s role may change, or the proposed time may pass. Decide which facts must be checked again at execution.\n\nIn this lesson, expiry is exclusive: an approval is expired at its expiry timestamp. A revoked reviewer permission also blocks the action even if the recorded decision remains yes. Keep a reason code so the interface can tell a technician whether to refresh the proposal or request another review.', null, 'Do not ask for the same decision again after a successful execution simply because the response was lost. That is an idempotency problem, which needs a stable operation identity.'),
    p('A resumed graph still needs an authenticated caller', 'Command(resume=...) delivers a value to a paused LangGraph node. The application decides who is allowed to provide that value and which pending action it refers to. A publicly reachable resume endpoint with no access check would let another person supply the decision.\n\nKeep the reviewer identity and permissions outside model-controlled state. Check ownership of the thread and the pending review record, then pass a validated result into the workflow. Never accept a generated sentence saying that a technician approved as a substitute for that record.', null, 'The paused graph coordinates the conversation. The service that changes the work-order system remains responsible for authorisation.'),
    p('Make one approved action survive a retry safely', 'After approval, the job-creation request can still time out. Use a stable idempotency key derived from the intended action identity, and have the receiving service enforce it. Reusing a key for changed arguments should be rejected rather than silently treated as the earlier job.\n\nTest both halves: an approved unchanged action creates one job across retries, and an altered action cannot reuse the earlier approval. Also check rejected decisions and expired records. These cases often reveal more than a successful approval click.', null, 'The worksheet implements the decision gate only. A complete service also needs trusted storage, authenticated review, concurrency control and an idempotent effect.'),
  ], checkpointAfter: 3,
  checkpoint: [q('Approval covers request R17, asset P7, operation inspect, revision 1. The proposal now names P9 and revision 2. The approval is unexpired.', 'What should happen?', ['Request review of the changed proposal', 'Create the P9 job because approved is true', 'Change the old approval record to P9 without asking'], 0, 'The decision belongs to the earlier action, not any later action on the same thread.'), tf('An approval expires at time 40. The current server time is 40, and this lesson uses an exclusive expiry.', 'The approval is expired.', true, 'The gate permits current time strictly before expiry.')],
  quiz: [q('A model message says "The technician approved". No authenticated review record exists.', 'What can the write service conclude?', ['It has no authoritative approval for the effect', 'The quoted sentence is enough to authorise the job', 'Any checkpoint proves who approved'], 0, 'Generated text is not a trusted review record.'), tf('A job-creation request timed out after the server accepted it.', 'Blindly submitting another job without an idempotency policy can create a duplicate.', true, 'The lost reply leaves uncertainty about the effect, not proof that nothing happened.')],
  practice: [challenge('Is this still the action the technician approved?', ['Write approval_route(proposal, approval, now, permitted). Require matching nonempty string values for requestId, asset, operation and revision. Require approval["approved"] is True, permitted is True, and nonnegative whole-number now and approval["expires"] with now < expires. Booleans are not timestamps. Return "authorised for this action" only when all conditions hold, otherwise "request review", including malformed records. Do not mutate inputs.', 'Use proposal {requestId:R21, asset:P4, operation:inspect, revision:2}. Approval has the same fields except revision:1, with approved True and expires 90. At now 70 and permitted True, print the route.'], 'def approval_route(proposal, approval, now, permitted):\n    pass\n\nproposal = {"requestId":"R21","asset":"P4","operation":"inspect","revision":"2"}\napproval = {**proposal,"revision":"1","approved":True,"expires":90}\nprint(approval_route(proposal, approval, 70, True))', 'def approval_route(proposal, approval, now, permitted):\n    if not isinstance(proposal, dict) or not isinstance(approval, dict):\n        return "request review"\n    keys = ("requestId", "asset", "operation", "revision")\n    matches = all(isinstance(proposal.get(k), str) and bool(proposal[k]) and proposal[k] == approval.get(k) for k in keys)\n    expires = approval.get("expires")\n    fresh = type(now) is int and type(expires) is int and 0 <= now < expires\n    valid = matches and fresh and approval.get("approved") is True and permitted is True\n    return "authorised for this action" if valid else "request review"\n\nproposal = {"requestId":"R21","asset":"P4","operation":"inspect","revision":"2"}\napproval = {**proposal,"revision":"1","approved":True,"expires":90}\nprint(approval_route(proposal, approval, 70, True))', 'request review', ['Compare every consequential field instead of only the request ID.', 'Use exact booleans for approval and permission. A string saying true should not grant authority.'], [['Unchanged authorised action', 'p = {"requestId":"A","asset":"P1","operation":"inspect","revision":"1"}\na = {**p,"approved":True,"expires":10}\nassert approval_route(p, a, 9, True) == "authorised for this action"'], ['Expiry boundary and revoked reviewer', 'p = {"requestId":"A","asset":"P1","operation":"inspect","revision":"1"}\na = {**p,"approved":True,"expires":10}\nassert approval_route(p, a, 10, True) == "request review"\nassert approval_route(p, a, 9, False) == "request review"'], ['Changed operation and malformed decision', 'p = {"requestId":"A","asset":"P1","operation":"inspect","revision":"1"}\na = {**p,"approved":True,"expires":10}\nassert approval_route({**p,"operation":"replace"}, a, 1, True) == "request review"\nassert approval_route(p, {**a,"approved":"true"}, 1, True) == "request review"'], ['Missing records fail closed', 'assert approval_route({}, {}, 0, True) == "request review"\nassert approval_route(None, {}, 0, True) == "request review"']])],
  build: build('Keep approval attached to the reviewed inspection', 'Botie has a proposed job and an earlier review decision. Check whether the decision still applies before the write boundary.', 'Match the proposal fields against the approval, compare current time with the supplied expiry, and require current reviewer permission. Combine all three boolean checks to return the authorisation route.', { proposal: 'Current proposal fields', approval: 'Authoritative approval fixture', now: 'Current server time', expires: 'Approval expiry time', permitted: 'Reviewer currently permitted?' }, [sample('The unchanged job is still approved', { proposal: { requestId: 'R17', asset: 'P7', operation: 'inspect', revision: '1' }, approval: { requestId: 'R17', asset: 'P7', operation: 'inspect', revision: '1', approved: true }, now: 20, expires: 40, permitted: true }, 'authorised for this action'), sample('The proposal changed after review', { proposal: { requestId: 'R17', asset: 'P9', operation: 'inspect', revision: '2' }, approval: { requestId: 'R17', asset: 'P7', operation: 'inspect', revision: '1', approved: true }, now: 20, expires: 40, permitted: true }, 'request review'), sample('The exact expiry boundary', { proposal: { requestId: 'R17', asset: 'P7', operation: 'inspect', revision: '1' }, approval: { requestId: 'R17', asset: 'P7', operation: 'inspect', revision: '1', approved: true }, now: 40, expires: 40, permitted: true }, 'request review')], op('afApprovalDecision', op('afBoundApproval', s('proposal'), s('approval')), op('afApprovalFresh', s('now'), s('expires')), s('permitted')), 'Matching, freshness and current authority answer different questions. Every one must pass for this action.', 'The records are trusted fixtures. Production approval must be authenticated, stored securely, checked atomically against the effect and paired with idempotent job creation.', ['Build the action comparison and time check on separate branches.', 'Require every approval check takes the two check outputs and current reviewer permission.']),
});

const mcpRecipe = `import anyio
from mcp import Client
from mcp.server import MCPServer

mcp = MCPServer("Perceptron Lab invented manuals")
MANUALS = {"P7": "Inspect the mounting and coupling."}

@mcp.tool()
def read_manual(asset: str) -> dict:
    """Read the invented excerpt for a named pump."""
    if asset not in MANUALS:
        return {"found": False, "asset": asset}
    return {"found": True, "asset": asset, "text": MANUALS[asset]}

@mcp.resource("manual://P7")
def p7_manual() -> str:
    """The invented P7 manual excerpt."""
    return MANUALS["P7"]

@mcp.prompt()
def inspection_question(asset: str) -> str:
    """Ask which inspection the supplied manual supports."""
    return f"Read the manual for {asset} and identify its inspection checks."

async def main():
    # In-process transport for a local test, with no model or network call.
    async with Client(mcp) as client:
        listed = await client.list_tools()
        assert "read_manual" in [tool.name for tool in listed.tools]
        result = await client.call_tool("read_manual", {"asset": "P7"})
        assert not result.is_error
        print(result.structured_content)

if __name__ == "__main__":
    anyio.run(main)`;

const mcp = lesson({
  id: 'agent-mcp', title: 'Connect Botie to Tools with MCP', topic: 'State and Permissions',
  appliedIn: [before('instructions arriving through tool content', 'agent-prompt-injection'), before('restricting what a tool may send outside', 'agent-data-boundaries')],
  blurb: 'Several assistants need the same maintenance tools. Share an interface while keeping server identity, permissions and returned content visible.',
  openingTitle: 'Why Write the Manual Connector Again for Every Assistant?',
  opening: ['The maintenance team now uses Botie in a web app and in an internal support tool. Both need the same manual lookup, but each integration describes and calls it differently. Maintaining two copies makes it easy for their behaviour to drift.', 'A shared protocol can describe what a server offers and how a client requests it. Model Context Protocol, or MCP, provides that interface. We will follow a manual lookup across the connection, then see why discovering a tool does not automatically make it safe or permitted to call.'],
  prerequisites: [before('Tool contracts', 'agent-tool-contracts'), before('Action-bound approval', 'agent-human-approval')],
  history: history('A Common Interface for Data Kept in Different Systems', [source('Anthropic: Introducing MCP, November 2024', 'https://www.anthropic.com/news/model-context-protocol'), source('MCP architecture', 'https://modelcontextprotocol.io/docs/learn/architecture'), source('Server concepts', 'https://modelcontextprotocol.io/docs/learn/server-concepts'), source('Official Python SDK', 'https://py.sdk.modelcontextprotocol.io/'), source('MCP trust assumptions', 'https://github.com/modelcontextprotocol/modelcontextprotocol/blob/main/SECURITY.md')], 'Assistants could generate text but often lacked a consistent connection to the systems holding a user’s documents and tools. Anthropic introduced MCP in November 2024 to standardise those integrations. A service can describe its capabilities through one protocol instead of requiring a separate custom interface for every assistant.', 'Our invented maintenance service uses that idea to expose manual content. Sharing a protocol does not settle whether a server is trustworthy, which technician may read a record, or whether a proposed action needs approval. Those decisions remain in the host application and the service that owns the data.'),
  reading: { experimentTitle: 'Which server would receive this lookup?', experimentIntro: 'Keep the server identity attached to the tool name, check the host allowlist, then resolve the registered handler.', connectionTitle: 'Shared interfaces still need explicit trust boundaries', practiceTitle: 'Practice. Resolve a permitted MCP endpoint', outputLabel: 'Selected handler or refusal reason', exampleNote: 'The workshop uses a local registry of labels. It does not open MCP connections or execute remote tools.' },
  intuition: [flow('Follow one lookup across the boundary', 'The host manages the model and user interface. Its client connection carries the request to the configured manual server.', [['Host application', 'Chooses permitted capabilities for this request'], ['MCP client connection', 'Names the server and sends read_manual arguments'], ['Manual server', 'Validates access and reads the excerpt'], ['Host again', 'Checks the result and provides it as evidence']], 'The model is not the network connection, and the server need not run a model.'), table('Two tools can have the same local name', 'The configured server is part of the identity. The host allowlist includes only maintenance/read_manual.', ['Qualified name', 'Handler label', 'Allowed?'], [['maintenance/read_manual', 'Read maintained pump excerpts', 'Yes'], ['community/read_manual', 'Read community notes', 'No']], 'Dropping the server name would make these different capabilities look interchangeable.')],
  parts: [
    p('Distinguish the host, client and server', 'The host is the application coordinating the user, model and available connections. An MCP client maintains a connection to a server. The server exposes capabilities such as reading maintenance records. A host can connect to several servers, each with a distinct scope and trust relationship.\n\nThat separation lets us put the manual integration beside the system that owns the manuals. The host can decide how much returned text enters a model request without moving all data ownership into the assistant.', null, 'MCP is an interface between programs. It is not itself an agent loop, a language model or a guarantee that an answer is correct.'),
    p('Choose whether something is a tool, resource or prompt', 'A tool exposes an operation with named arguments, such as read_manual(asset). Tools can read or write; the word tool does not imply that every invocation changes state. A resource exposes content at an identifier such as manual://P7. A prompt supplies a reusable message template a user can choose.\n\nThese roles suggest different interfaces: a tool call, a document the application can include, or a prompt menu. They do not override permission checks. A read operation can reveal private data, and a prompt template can contain instructions the host should inspect before trusting.', null, 'The same manual service can offer several of these capabilities because they answer different application needs.'),
    p('Discover a capability before calling it', 'The client establishes the connection and negotiates the protocol features supported by the server. Listing tools returns descriptions and input schemas. The host can select permitted definitions to make available to a model, then send a requested name and arguments to the correct server.\n\nA schema describes the argument shape. It does not prove that an asset belongs to the technician or that a URL is safe to fetch. The receiving service still validates both data and access. If a server paginates discovery results, the client must follow its cursor rather than assuming one page contains everything.', null, 'Keep discovery, selection and execution distinct in the trace. A tool can be listed successfully while a particular call is correctly denied.'),
    withRef(p('Expose the invented manual service in Python', 'The reference defines a tool, a fixed resource and a prompt. It then uses an in-process client to discover and call the tool without a model. That is enough to test the service interface before adding an agent that chooses calls.\n\nThe example follows the current official Python SDK 2.x API. Older tutorials often use FastMCP from mcp.server.fastmcp; do not mix imports from different major versions. Pin your resolved environment once the example works.', null, 'The result describes the fixture’s lookup. No model decides what to request in this program.'), ref('A manual server and a local protocol test', 'This is a standalone service reference using the official MCP Python SDK. Its test stays inside one Python process.', mcpRecipe, ['Use Python 3.11 or later in a separate environment. Install mcp>=2,<3 and anyio, then record resolved versions in a lockfile.', 'No provider API key is needed for this program. The Client receives the server object for an in-process test.', 'The fixture has no authentication because it contains only invented public text and is not exposed on a network. Add real access control before connecting private data or deploying a network server.'], 'The SDK builds the tool schema from the signature. The application still needs to handle tool failures and decide what content to trust.', 'https://py.sdk.modelcontextprotocol.io/')),
    p('Read the result before treating it as evidence', 'A completed transport request can carry a tool failure. Inspect the result’s error status before reading structured data as a success. Also distinguish an application outcome such as found = False from a failure to contact the service at all.\n\nThe returned content may include text and other content blocks. Preserve provenance when adding it to context: which server returned it, from which record, and at what revision? Text that says to change the assistant’s rules is still returned content, not new authority over the host.', null, 'The typed client API uses its documented Python field names. A raw protocol JSON payload may spell fields differently, so do not interchange the two representations by guesswork.'),
    p('Keep the configured server identity with the tool', 'Suppose the maintenance service and a community-notes service both expose read_manual. If the host indexes tools only by their local name, one can accidentally replace the other. Use an unambiguous mapping from the model-visible tool to its configured connection and local name.\n\nThe workshop writes that mapping as server/tool for readability. This slash convention is our local teaching registry, not an MCP naming requirement. The allowlist uses the same qualified identity, so permitting maintenance/read_manual does not also permit community/read_manual.', null, 'If a permitted tool disappears, report it as unavailable. Quietly falling back to a similarly named tool would change the source and possibly its authority.', [example('Preserve the connection when indexing a discovered tool', 'The list holds two discovery records. Each dictionary has a server field and a local tool name. Constructing both labels before using a set keeps the two identities distinct.', 'discovered = [\n    {"server": "maintenance", "tool": "read_manual"},\n    {"server": "archive", "tool": "read_manual"},\n]\nqualified = [item["server"] + "/" + item["tool"] for item in discovered]\nprint(qualified)\nprint(len(set(qualified)))', "['maintenance/read_manual', 'archive/read_manual']\n2", 'Two distinct qualified names remain. A set containing only the local tool name would collapse these records and lose their connection identity.')]),
    p('A local server still runs real code', 'A server launched over standard input and output is a local program with the permissions of its process. Connecting it does not automatically confine its filesystem or network access. Review the program, its configuration and the permissions it receives.\n\nA remote service brings another trust boundary. Imagine the maintenance server accepting a token intended for the payroll service just because the token has a valid signature. The signature tells us who issued it; we still have to check who may use it and where. An HTTP MCP server using the protocol’s authorisation scheme must validate that a token was issued for that server. It must not pass the incoming token through to a downstream API.\n\nKeep credentials in the host or service environment. Grant the scopes needed for this job, and check object access inside the receiving service. Tool descriptions and annotations are claims from the server, not independent proof of its behaviour.', null, 'Start with a narrow read-only integration and invented fixtures. Add a write tool only after the approval and idempotency rules from the preceding lesson are enforced by the effect-owning service.'),
    p('Test the connection without confusing it with task quality', 'A protocol test can establish that a tool is discoverable, accepts the expected arguments and returns the expected fixture. The workshop adds a host routing check, including a same-name tool on a different server. Those are useful integration tests.\n\nA separate agent evaluation must ask whether Botie chose the right capability and used its output correctly. Keep both layers. When a technician receives an unsupported answer, we want to distinguish a misrouted lookup from an incorrect interpretation of a correctly retrieved excerpt.', null, 'The next work is observing a complete run so we can see where a failure began, rather than judging only the final sentence.'),
  ], checkpointAfter: 3,
  checkpoint: [q('A service offers read_manual(asset), content at manual://P7, and an inspection-question message template.', 'Which item is a resource?', ['The content at manual://P7', 'Every function with arguments', 'The model’s final generated answer'], 0, 'The resource exposes content through an identifier.'), tf('An MCP server lists a create_job tool successfully. The current user lacks permission to create jobs.', 'Discovery authorises the user to run create_job.', false, 'Discovery advertises a capability. Access policy still governs execution.')],
  quiz: [q('maintenance/read_manual and community/read_manual have the same local name. Only the maintenance endpoint is allowed.', 'What must the host preserve when routing?', ['The configured server identity as well as the tool name', 'Only the local tool name', 'Whichever description sounds more confident'], 0, 'Names from different servers can collide; they represent different endpoints.'), tf('A protocol fixture returns the right manual excerpt when called directly.', 'That test alone proves the agent will select the right tool for every technician question.', false, 'The test checks the interface, not the model’s selection or use of the result.')],
  practice: [challenge('Can a same-name tool on another server sneak into the route?', ['Write resolve_tool(request, allowed, registry). request is a dictionary with nonempty string server and tool fields, neither containing a slash. allowed is a list of server/tool strings. registry maps server/tool strings to text handler labels. Return "blocked" if the qualified request is not allowed, "unavailable" if allowed but absent from registry, otherwise the registered label. Malformed inputs raise ValueError. This function selects a label only; it must not execute code or connect to a server.', 'Print the result for request {server:community, tool:read_manual}, allowed [maintenance/read_manual], and a registry containing both names.'], 'def resolve_tool(request, allowed, registry):\n    pass\n\nregistry = {"maintenance/read_manual":"Maintained excerpts","community/read_manual":"Community notes"}\nprint(resolve_tool({"server":"community","tool":"read_manual"}, ["maintenance/read_manual"], registry))', 'def resolve_tool(request, allowed, registry):\n    if not isinstance(request, dict):\n        raise ValueError("Request must be a record")\n    for key in ("server", "tool"):\n        value = request.get(key)\n        if not isinstance(value, str) or not value or "/" in value:\n            raise ValueError("Use nonempty names without slashes")\n    if not isinstance(allowed, list) or any(not isinstance(x, str) for x in allowed):\n        raise ValueError("Allowed endpoints must be a string list")\n    if not isinstance(registry, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k,v in registry.items()):\n        raise ValueError("Registry must map text names to text labels")\n    qualified = request["server"] + "/" + request["tool"]\n    if qualified not in allowed:\n        return "blocked"\n    return registry.get(qualified, "unavailable")\n\nregistry = {"maintenance/read_manual":"Maintained excerpts","community/read_manual":"Community notes"}\nprint(resolve_tool({"server":"community","tool":"read_manual"}, ["maintenance/read_manual"], registry))', 'blocked', ['Build the qualified name before checking the allowlist.', 'An allowed but missing endpoint must not fall back to another server with the same local name.'], [['Permitted qualified identity', 'assert resolve_tool({"server":"plant","tool":"read"}, ["plant/read"], {"plant/read":"handler"}) == "handler"'], ['No name-only fallback', 'assert resolve_tool({"server":"plant","tool":"read"}, ["plant/read"], {"other/read":"wrong"}) == "unavailable"'], ['Same tool on another server', 'assert resolve_tool({"server":"other","tool":"read"}, ["plant/read"], {"other/read":"wrong"}) == "blocked"'], ['Reject ambiguous separator', 'try:\n    resolve_tool({"server":"plant/other","tool":"read"}, [], {})\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError("Expected ValueError")']])],
  build: build('Route the lookup to the intended manual service', 'Two connected services expose a read_manual tool. The host must retain their separate identities and permissions.', 'Build a server-qualified tool name, check it against the allowed endpoint list, and resolve the result in the registered handler labels. Return blocked for a disallowed endpoint and unavailable for a permitted endpoint absent from the registry.', { request: 'Requested server and tool', allowed: 'Permitted server-qualified endpoints', registry: 'Registered endpoint labels' }, [sample('The maintained manual service', { request: { server: 'maintenance', tool: 'read_manual' }, allowed: ['maintenance/read_manual'], registry: { 'maintenance/read_manual': 'Maintained pump excerpts', 'community/read_manual': 'Community notes' } }, 'Maintained pump excerpts'), sample('A same-name tool on another server', { request: { server: 'community', tool: 'read_manual' }, allowed: ['maintenance/read_manual'], registry: { 'maintenance/read_manual': 'Maintained pump excerpts', 'community/read_manual': 'Community notes' } }, 'blocked'), sample('A permitted tool has disappeared', { request: { server: 'maintenance', tool: 'read_manual' }, allowed: ['maintenance/read_manual'], registry: { 'community/read_manual': 'Community notes' } }, 'unavailable')], op('afResolveEndpoint', op('afAllowedEndpoint', op('afQualifiedTool', s('request')), s('allowed')), s('registry')), 'The host retains connection identity through discovery, permission and dispatch. A local name alone cannot identify the intended capability.', 'The slash names and label registry are a teaching model. Real MCP clients also negotiate capabilities, validate arguments, authenticate and handle transport and tool failures.', ['Keep the server with the tool first. Both are part of the identity.', 'The allowlist output is either a permitted name or null. Resolve it only after that check.']),
});

